#include <stdio.h>

/* teste do desafio include-proprio — counter_protocol (03-tdd 3.9.3).
   O main e o relatorio sao do harness; aqui so existem cenarios SM_TEST.
   Sem a linha do include no arquivo do aluno este desafio nem compila —
   e falhar na compilacao e a prova de que a lista de cima e necessaria. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
void includeProprio(void);

SM_TEST(as_duas_linhas_da_lista) {
    freopen("sm_saida.tmp", "w", stdout);
    includeProprio();
    fflush(stdout);

    FILE *f = fopen("sm_saida.tmp", "r");
    char linha[80] = "(nada impresso)";
    fgets(linha, 80, f);
    checa_str("a primeira linha", linha, "a lista de cima apresenta o printf\n",
              "a primeira frase sai do primeiro printf, que so existe porque a lista o apresentou");
    fgets(linha, 80, f);
    checa_str("a segunda linha", linha, "sem ela o compilador nao compila\n",
              "a segunda frase vem depois da quebra de linha da primeira");
    char fim[80] = "(nada impresso)";
    fgets(fim, 80, f);
    checa_str("nao ha linha a mais", fim, "(nada impresso)",
              "a saida acaba na segunda linha: nenhuma linha extra e aceita");
    fclose(f);
}

